<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Salary Slip</title><style>@page{size:A4 portrait;margin:18mm}body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:11px}.sheet{border:1px solid #94a3b8;padding:20px}.header{text-align:center;border-bottom:2px solid #1e3a8a;padding-bottom:12px}.school{font-size:22px;font-weight:bold;color:#1e3a8a}.title{font-size:15px;font-weight:bold;margin-top:8px}.info,.amounts{width:100%;border-collapse:collapse;margin-top:16px}.info td,.amounts th,.amounts td{border:1px solid #94a3b8;padding:7px}.amounts th{background:#e0e7ff;color:#1e3a8a;text-align:left}.amount{text-align:right}.net{margin-top:16px;border:2px solid #1e3a8a;padding:12px;text-align:right;font-size:15px;font-weight:bold}.attendance{margin-top:10px;color:#475569}.signatures{margin-top:70px;width:100%}.signature{display:inline-block;width:32%;text-align:center}.line{display:inline-block;border-top:1px solid #111827;padding-top:5px;width:75%}</style></head><body><div class="sheet"><div class="header"><div class="school">{{ $data['school']['name_en'] }}</div><div>{{ $data['school']['address_en'] }}</div><div class="title">SALARY SLIP — {{ $data['payslip']['period'] }}</div></div><table class="info"><tr><td><strong>Employee</strong><br>{{ $data['employee']['name'] }}</td><td><strong>Employee Code</strong><br>{{ $data['employee']['code'] }}</td><td><strong>Designation</strong><br>{{ $data['employee']['designation'] }}</td></tr><tr><td><strong>Department</strong><br>{{ $data['employee']['department'] ?: '—' }}</td><td><strong>Slip No.</strong><br>{{ $data['payslip']['slip_no'] }}</td><td><strong>Bank Account</strong><br>{{ $data['employee']['bank_account_no'] ?: '—' }}</td></tr></table><table class="amounts"><thead><tr><th>Earnings</th><th class="amount">Amount (BDT)</th></tr></thead><tbody>@foreach($data['earnings'] as $item)<tr><td>{{ $item['name'] }}</td><td class="amount">{{ $item['amount'] }}</td></tr>@endforeach<tr><th>Gross Earnings</th><th class="amount">{{ $data['payslip']['gross_earnings'] }}</th></tr></tbody></table><table class="amounts"><thead><tr><th>Deductions</th><th class="amount">Amount (BDT)</th></tr></thead><tbody>@forelse($data['deductions'] as $item)<tr><td>{{ $item['name'] }}</td><td class="amount">{{ $item['amount'] }}</td></tr>@empty<tr><td>No deductions</td><td class="amount">0.00</td></tr>@endforelse<tr><th>Total Deductions</th><th class="amount">{{ $data['payslip']['total_deductions'] }}</th></tr></tbody></table><div class="attendance">Attendance: Present {{ $data['attendance']['present_days'] }} · Absent {{ $data['attendance']['absent_days'] }} · Leave {{ $data['attendance']['leave_days'] }}</div><div class="net">Net Payable: BDT {{ $data['payslip']['net_payable'] }}<br><small>{{ $data['payslip']['net_payable_words'] }}</small></div><div class="signatures"><div class="signature"><span class="line">Employee</span></div><div class="signature"><span class="line">Accounts Officer</span></div><div class="signature"><span class="line">Principal / Head Teacher</span></div></div></div></body></html>
